def load_src_rs_buttons(path="rev64/forward/src_rs/ui_menu.c"):
    """从 ui_menu.c 解析按钮表（g_btns/g_diff_btns/... 720×1280 基准）"""
    txt = open(path).read()
    tables = {}
    # g_btns[5] 主菜单
    m = re.findall(r"\{\s*([\d.]+)f\s*,\s*([\d.]+)f\s*,\s*([\d.]+)f\s*,\s*([\d.]+)f\s*,\s*\"([^\"]+)\"", txt)
    tables["menu"] = [(float(a),float(b),float(c),float(d),e) for a,b,c,d,e in m[:5]]
    # ★ P1（datah_016/017/020）：布局存档 3 按钮表（5 元素 x0f,y0f,x1f,y1f,action 行，
    #   按 g_loadlayout_btns / g_savelayout_btns / g_laymgr_btns 注释锚点定位）
    def _grab(table_marker):
        """取 table_marker 注释后到下一个 static const 间的 5 元素行"""
        i = txt.find(table_marker)
        if i < 0: return []
        j = txt.find("static const", i + 10)
        seg = txt[i:j if j > 0 else len(txt)]
        mm = re.findall(r"\{\s*([\d.]+)f\s*,\s*([\d.]+)f\s*,\s*([\d.]+)f\s*,\s*([\d.]+)f\s*,\s*(\d+)\s*\}", seg)
        return [(float(x),float(y),float(x1),float(y1),int(ac)) for x,y,x1,y1,ac in mm]
    tables["loadlay"] = _grab("g_loadlayout_btns")
    tables["savelay"] = _grab("g_savelayout_btns")
    tables["laymgr"] = _grab("g_laymgr_btns")
    # ★ P1（datah_107 证据）：复盘回放控制条 5 按钮（g_replay_ctrl_btns）
    tables["replay"] = _grab("g_replay_ctrl_btns")
    # ★ P1（datah_038 证据）：登录弹窗 6 控件（g_login_btns）
    tables["login"] = _grab("g_login_btns")
    # ★ P2（datah_037 证据）：规则文本弹窗 3 按钮（g_rules_btns）
    tables["rules"] = _grab("g_rules_btns")
    # ★ P2（datah_104 证据）：新局完整版弹窗 5 控件（g_newgame104_btns）
    tables["ng104"] = _grab("g_newgame104_btns")
    # ★ P2（datah_034 证据）：加入游戏弹窗 3 控件（g_join_btns）
    tables["join"] = _grab("g_join_btns")
    # ★ P2（datah_035 证据）：创建游戏弹窗 3 控件（g_create_btns）
    tables["create"] = _grab("g_create_btns")
    # ★ P2（datah_061 证据）：新局完整版（完整版补充）弹窗 6 控件（g_ng061_btns）
    tables["ng061"] = _grab("g_ng061_btns")
    # ★ P2（datah_050 证据）：对局信息弹窗 3 按钮（g_gameinfo_btns）
    tables["gameinfo"] = _grab("g_gameinfo_btns")
    # ★ P2（datah_002 证据）：亮度调节弹窗 3 控件（g_bright_btns）
    tables["bright"] = _grab("g_bright_btns")
    # ★ P2（datah_029 证据）：聊天记录弹窗 2 按钮（g_chatlog_btns）
    tables["chatlog"] = _grab("g_chatlog_btns")
    # ★ P2（datah_031 证据）：个人资料弹窗 3 按钮（g_profile_btns）
    tables["profile"] = _grab("g_profile_btns")
    # ★ P2（datah_042 证据）：提和详情弹窗 7 图标（g_drawdetail_btns）
    tables["drawdetail"] = _grab("g_drawdetail_btns")
